import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller) public {
        // Restrict inputs: caller must be the current owner and newOwner can be any address
        c.transferOwnership(caller);
        vm.assume(caller == c.owner());
        address ownerBefore = c.owner();

        // Call owned() which does nothing
        c.owned();

        address ownerAfter = c.owner();
        assertTrue(ownerBefore == ownerAfter, "owned() should not change the owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != caller);
        // Set initial owner to a known address
        address initialOwner = address(0x1234);
        c.transferOwnership(initialOwner);
        // Ensure caller is the owner, transfer to newOwner
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);
        // Now call owned() as the caller (not the owner)
        vm.prank(caller);
        c.owned();
        // The owner should still be newOwner (not caller)
        assertTrue(c.owner() == newOwner);
    }
}
